        assertTrue(finance.get(1).body().contains(TextFormat.money(reservation.price().total())));
    }

    @Test
    void noRefundMeansFinanceIsNotTold() {
        Reservation reservation = service.create(stay(201, "2027-03-10", "2027-03-12", 2, RatePlan.NON_REFUNDABLE));
        service.confirm(reservation.id());

        service.cancel(reservation.id());

        assertEquals(2, sentTo("governanca@pousadamarealta.com.br").size());
        assertEquals(1, sentTo("financeiro@pousadamarealta.com.br").size());
    }

    @Test
    void cancellingAPendingReservationTellsNoOne() {
        Reservation reservation = service.create(stay(201, "2027-03-10", "2027-03-12", 2, RatePlan.STANDARD));

        service.cancel(reservation.id());

        assertEquals(0, sentMessages.all().size());
    }

    @Test
    void anyListenerCanBePlugged() {
        List<String> seen = new java.util.ArrayList<>();
        ReservationService custom = new ReservationService(
                new Rooms(database.dataSource()), new ReservationStore(database.dataSource()), new PriceCalculator(),
                new EmailSender(sentMessages), List.of(new ReservationListener() {
                    @Override
                    public void onConfirmed(Confirmed event) {
                        seen.add("confirmed " + event.room().number());
                    }
                }));
        Reservation reservation = custom.create(stay(201, "2027-03-10", "2027-03-12", 2, RatePlan.STANDARD));

        custom.confirm(reservation.id());

        assertEquals(List.of("confirmed 201"), seen);
        assertEquals(1, sentMessages.all().size());
    }
